    non_bg_non_target = []
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != background and val != target_color:
                non_bg_non_target.append(val)

    if not non_bg_non_target:
        return result

    cnt = Counter(non_bg_non_target)
    converter_color = max(cnt, key=cnt.get)

    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == converter_color and (r, c) not in visited:
                component = []
                queue = [(r, c)]
                visited.add((r, c))

