                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == converter_color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                # Check if this component forms a perfect 3-cell L-shape
                if len(component) == 3:
                    deg_counts = Counter()
                    for cr, cc in component:
                        neighbors = []
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == converter_color:
                                    neighbors.append((nr, nc))
                        deg_counts[len(neighbors)] += 1

